/* Ensure hidden attribute overrides display rules */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b2b36;
  --card-bg: #fff8e7;
  --card-border: #1f1f29;
  --text-main: #1f1f29;
  --primary: #f59e0b;
  --primary-hover: #d97706;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --progress-fill: #10b981;
  --white: #ffffff;
  --shadow: #0e0e14;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  font-family: 'Courier New', Courier, monospace, monospace;
  font-size: 16px;
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.app-container {
  width: 100%;
  max-width: 440px;
}

.timer-card {
  background: var(--card-bg);
  border: 4px solid var(--card-border);
  box-shadow: 8px 8px 0px var(--shadow);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.timer-header .title {
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: 2px;
  margin-bottom: 12px;
  text-transform: uppercase;
}

.egg-stage {
  margin: 8px 0 16px;
  background: #fef3c7;
  border: 3px solid var(--card-border);
  box-shadow: 4px 4px 0px var(--card-border);
  padding: 8px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.status-banner {
  min-height: 1.8rem;
  font-weight: bold;
  font-size: 1.15rem;
  margin-bottom: 8px;
  color: var(--text-main);
}

.status-banner.done {
  color: #b91c1c;
  animation: pixel-pulse 0.8s steps(2, start) infinite;
}

@keyframes pixel-pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.06); }
  100% { transform: scale(1); }
}

.time-display {
  font-size: 3rem;
  font-weight: 900;
  letter-spacing: 3px;
  margin-bottom: 14px;
  padding: 6px 16px;
  background: #ffffff;
  border: 3px solid var(--card-border);
  box-shadow: inset 3px 3px 0px #cbd5e1;
  width: 100%;
  max-width: 260px;
}

.progress-track {
  width: 100%;
  height: 24px;
  background: #ffffff;
  border: 3px solid var(--card-border);
  margin-bottom: 20px;
  overflow: hidden;
  box-shadow: inset 2px 2px 0px #e2e8f0;
}

.progress-bar {
  height: 100%;
  width: 0%;
  background-color: var(--progress-fill);
  transition: width 0.2s linear;
}

.preset-controls,
.action-controls {
  display: flex;
  gap: 8px;
  width: 100%;
  margin-bottom: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.action-controls {
  margin-bottom: 0;
}

.pixel-btn {
  flex: 1 1 95px;
  min-height: 44px;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: bold;
  background: #ffffff;
  color: var(--text-main);
  border: 3px solid var(--card-border);
  box-shadow: 3px 3px 0px var(--card-border);
  cursor: pointer;
  padding: 8px 10px;
  text-transform: uppercase;
  transition: none;
}

.preset-btn.active {
  background-color: var(--primary);
  color: #ffffff;
}

.pixel-btn:hover:not(:disabled) {
  background-color: #f1f5f9;
}

.preset-btn.active:hover:not(:disabled) {
  background-color: var(--primary-hover);
}

.action-btn {
  background-color: #e2e8f0;
}

#btn-pause {
  background-color: #fed7aa;
}

#btn-resume {
  background-color: #bbf7d0;
}

#btn-reset {
  background-color: #fecdd3;
}

.pixel-btn:focus-visible {
  outline: 3px dashed #2563eb;
  outline-offset: 2px;
}

.pixel-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px var(--card-border);
}

.pixel-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: 1px 1px 0px var(--card-border);
  transform: none;
}

@media (max-width: 360px) {
  .time-display {
    font-size: 2.4rem;
  }
  .timer-card {
    padding: 16px 12px;
  }
  .pixel-btn {
    font-size: 0.85rem;
    padding: 6px 4px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const eggCanvas = document.getElementById('egg-canvas');
  const ctx = eggCanvas ? eggCanvas.getContext('2d') : null;

  const timerDisplay = document.getElementById('timer-display');
  const progressBar = document.getElementById('progress-bar');
  const progressContainer = document.getElementById('progress-container');
  const statusMessage = document.getElementById('status-message');

  const btnSoft = document.getElementById('btn-soft');
  const btnMedium = document.getElementById('btn-medium');
  const btnHard = document.getElementById('btn-hard');
  const btnPause = document.getElementById('btn-pause');
  const btnResume = document.getElementById('btn-resume');
  const btnReset = document.getElementById('btn-reset');

  const presetButtons = [btnSoft, btnMedium, btnHard];

  let totalDurationSeconds = 0;
  let remainingSeconds = 0;
  let timerInterval = null;
  let isPaused = false;
  let currentPreset = null;

  function formatTime(totalSec) {
    const mins = Math.floor(totalSec / 60);
    const secs = totalSec % 60;
    const paddedSecs = secs < 10 ? `0${secs}` : `${secs}`;
    return `${mins}:${paddedSecs}`;
  }

  function updateProgress() {
    if (totalDurationSeconds <= 0) {
      progressBar.style.width = '0%';
      progressContainer.setAttribute('aria-valuenow', '0');
      return;
    }
    const elapsed = totalDurationSeconds - remainingSeconds;
    const percentage = Math.min(100, Math.max(0, (elapsed / totalDurationSeconds) * 100));
    progressBar.style.width = `${percentage.toFixed(1)}%`;
    progressContainer.setAttribute('aria-valuenow', Math.round(percentage).toString());
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);
    updateProgress();
  }

  function drawPixelEgg(state = 'idle') {
    if (!ctx) return;
    ctx.clearRect(0, 0, eggCanvas.width, eggCanvas.height);

    const scale = 5;
    // 16x20 pixel grid representation of an egg
    const eggMap = [
      '....XXXXXX......',
      '..XXOOOOOOXX....',
      '.XOOOOOOOOOOX...',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      'XOOOOOOOOOOOOX..',
      '.XOOOOOOOOOOX...',
      '..XXOOOOOOXX....',
      '....XXXXXX......'
    ];

    const colorShell = '#ffffff';
    const colorOutline = '#1f1f29';
    const colorShadow = '#e2e8f0';
    const colorDoneYolk = '#f59e0b';

    const offsetX = 20;
    const offsetY = 25;

    for (let r = 0; r < eggMap.length; r++) {
      const row = eggMap[r];
      for (let c = 0; c < row.length; c++) {
        const char = row[c];
        if (char === '.') continue;

        if (char === 'X') {
          ctx.fillStyle = colorOutline;
        } else if (char === 'O') {
          if (state === 'done') {
            // Show cooked inner color
            ctx.fillStyle = (r > 6 && r < 12 && c > 4 && c < 11) ? colorDoneYolk : colorShell;
          } else if (c > 10 || r > 11) {
            ctx.fillStyle = colorShadow;
          } else {
            ctx.fillStyle = colorShell;
          }
        }
        ctx.fillRect(offsetX + c * scale, offsetY + r * scale, scale, scale);
      }
    }

    // Cute pixel eyes and expressions
    ctx.fillStyle = colorOutline;
    if (state === 'done') {
      // Happy closed eyes (^ ^)
      ctx.fillRect(offsetX + 6 * scale, offsetY + 8 * scale, scale * 2, scale);
      ctx.fillRect(offsetX + 10 * scale, offsetY + 8 * scale, scale * 2, scale);
      ctx.fillRect(offsetX + 8 * scale, offsetY + 10 * scale, scale * 2, scale);
    } else if (state === 'running') {
      // Open focused eyes
      ctx.fillRect(offsetX + 6 * scale, offsetY + 7 * scale, scale, scale * 2);
      ctx.fillRect(offsetX + 11 * scale, offsetY + 7 * scale, scale, scale * 2);
      ctx.fillRect(offsetX + 8 * scale, offsetY + 10 * scale, scale * 2, scale);
    } else if (state === 'paused') {
      // Neutral sleepy eyes (- -)
      ctx.fillRect(offsetX + 6 * scale, offsetY + 8 * scale, scale * 2, scale);
      ctx.fillRect(offsetX + 10 * scale, offsetY + 8 * scale, scale * 2, scale);
    } else {
      // Regular idle face
      ctx.fillRect(offsetX + 6 * scale, offsetY + 8 * scale, scale, scale);
      ctx.fillRect(offsetX + 11 * scale, offsetY + 8 * scale, scale, scale);
      ctx.fillRect(offsetX + 8 * scale, offsetY + 11 * scale, scale * 2, scale);
    }
  }

  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds--;
      updateDisplay();
      if (remainingSeconds === 0) {
        finishTimer();
      }
    }
  }

  function startTimer() {
    stopTimer();
    timerInterval = setInterval(tick, 1000);
  }

  function finishTimer() {
    stopTimer();
    isPaused = false;
    statusMessage.textContent = 'Eggs are done!';
    statusMessage.classList.add('done');
    btnPause.disabled = true;
    btnResume.disabled = true;
    drawPixelEgg('done');
  }

  function selectPreset(presetName, minutes, buttonEl) {
    currentPreset = presetName;
    totalDurationSeconds = minutes * 60;
    remainingSeconds = totalDurationSeconds;
    isPaused = false;

    presetButtons.forEach(btn => btn.classList.remove('active'));
    buttonEl.classList.add('active');

    statusMessage.textContent = `Boiling ${presetName} egg...`;
    statusMessage.classList.remove('done');

    btnPause.disabled = false;
    btnResume.disabled = true;

    updateDisplay();
    drawPixelEgg('running');
    startTimer();
  }

  btnSoft.addEventListener('click', () => selectPreset('Soft', 6, btnSoft));
  btnMedium.addEventListener('click', () => selectPreset('Medium', 8, btnMedium));
  btnHard.addEventListener('click', () => selectPreset('Hard', 10, btnHard));

  btnPause.addEventListener('click', () => {
    if (timerInterval && remainingSeconds > 0 && !isPaused) {
      stopTimer();
      isPaused = true;
      btnPause.disabled = true;
      btnResume.disabled = false;
      statusMessage.textContent = 'Paused';
      drawPixelEgg('paused');
    }
  });

  btnResume.addEventListener('click', () => {
    if (isPaused && remainingSeconds > 0) {
      isPaused = false;
      btnPause.disabled = false;
      btnResume.disabled = true;
      statusMessage.textContent = `Boiling ${currentPreset || ''} egg...`;
      drawPixelEgg('running');
      startTimer();
    }
  });

  btnReset.addEventListener('click', () => {
    stopTimer();
    isPaused = false;
    totalDurationSeconds = 0;
    remainingSeconds = 0;
    currentPreset = null;
    presetButtons.forEach(btn => btn.classList.remove('active'));
    btnPause.disabled = true;
    btnResume.disabled = true;
    statusMessage.textContent = 'Select doneness';
    statusMessage.classList.remove('done');
    updateDisplay();
    drawPixelEgg('idle');
  });

  // Initial render
  updateDisplay();
  drawPixelEgg('idle');
});
